import re


def calc(expr):
    tokens = re.findall(r"\d+\.?\d*|[-+*/]", expr.replace(" ", ""))
    # 1단계: 곱셈·나눗셈 먼저
    stack = [float(tokens[0])]
    i = 1
    while i < len(tokens):
        op, num = tokens[i], float(tokens[i + 1])
        if op == "*":
            stack[-1] *= num
        elif op == "/":
            stack[-1] /= num
        else:
            stack.append(op)
            stack.append(num)
        i += 2
    # 2단계: 남은 덧셈·뺄셈을 왼쪽부터
    result = stack[0]
    for j in range(1, len(stack), 2):
        if stack[j] == "+":
            result += stack[j + 1]
        else:
            result -= stack[j + 1]
    return result

